// No AI footer in a pull request's body or commit messages (build rule 38, Nov 4, 2026).
// The real cases: #316's body ended with the platform's "Generated with [Claude Code]" footer and a
// claude.ai/code link; #304's body ended "_Generated by [Claude Code](...)_" and its squash commit carried
// Co-Authored-By: Claude and Claude-Session: lines onto main. scripts/dev/ai_footer_check.py is the guard,
// run by the PR checks' guard job; its selftest holds those texts.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

test('the footer check fails #316\'s body and #304\'s squash message, and passes them stripped', () => {
  const out = execFileSync('python3', ['scripts/dev/ai_footer_check.py', '--selftest'], { cwd: root, encoding: 'utf8' });
  assert.match(out, /all ai_footer_check checks passed/);
  assert.match(out, /ok {3}#316's body fails, both footer lines named/);
  assert.match(out, /ok {3}#304's squash message in a commit warns on its 3 lines; the body passes/);
  assert.match(out, /ok {3}strip: #304's lines and the --- rule between them go/);
});

test('a pull request run with #316\'s body and no API fails on the body; a run with no pull request passes', () => {
  const tmp = fs.mkdtempSync(path.join(process.env.TMPDIR || '/tmp', 'aifoot-'));
  const ev = path.join(tmp, 'event.json');
  const body = 'Fixes the PR #315 CI failure.\n\n\u{1F916} Generated with [Claude Code](https://claude.com/claude-code)\n';
  fs.writeFileSync(ev, JSON.stringify({ pull_request: { number: 316, body } }));
  // the API is a closed local port: the body falls back to the event and fails; unread commits are only said
  const env = { ...process.env, GITHUB_EVENT_PATH: ev, GITHUB_REPOSITORY: 'dnilgis/agsist', GITHUB_API_URL: 'http://127.0.0.1:9', GH_TOKEN: '' };
  const r = spawnSync('python3', ['scripts/dev/ai_footer_check.py'], { cwd: root, encoding: 'utf8', env });
  assert.equal(r.status, 1, r.stdout + r.stderr);
  assert.match(r.stdout, /commits could not be read/);
  assert.match(r.stdout, /AI footer line\(s\) in the pull request body/);
  const clean = path.join(tmp, 'clean.json');
  fs.writeFileSync(clean, JSON.stringify({ pull_request: { number: 316, body: 'Fixes the PR #315 CI failure.' } }));
  const ok = spawnSync('python3', ['scripts/dev/ai_footer_check.py'], { cwd: root, encoding: 'utf8', env: { ...env, GITHUB_EVENT_PATH: clean } });
  assert.equal(ok.status, 0, ok.stdout + ok.stderr);
  const none = spawnSync('python3', ['scripts/dev/ai_footer_check.py'], { cwd: root, encoding: 'utf8', env: { ...env, GITHUB_EVENT_PATH: path.join(tmp, 'none.json') } });
  assert.equal(none.status, 0, none.stdout + none.stderr);
  fs.rmSync(tmp, { recursive: true, force: true });
});

test('prose that names a footer form passes and keeps its line in the squash; the real #304 and #316 footers fail', () => {
  const run = (code) => spawnSync('python3', ['-c', 'import sys, json; sys.path.insert(0, "scripts/dev")\nimport ai_footer_check as A\n' + code], { cwd: root, encoding: 'utf8' });
  const prose = ['Notes.', 'lines like `Co-Authored-By: Claude` are stripped', 'Docs at https://claude.ai/code'].join('\n');
  let r = run('t = sys.argv[1]\nprint(json.dumps([A.check(t, [])[0], A.strip(t)]))'.replace('sys.argv[1]', JSON.stringify(prose)));
  assert.deepEqual(JSON.parse(r.stdout), [true, prose], r.stderr);
  r = run('print(json.dumps([A.check(A.REAL_316, [])[0], A.check(A.REAL_304_BODY, [])[0], A.check(A.REAL_304, [])[0]]))');
  assert.deepEqual(JSON.parse(r.stdout), [false, false, false], r.stderr);
  r = run('print(json.dumps(A.strip("Body.\\n\\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>\\n")))');
  assert.equal(JSON.parse(r.stdout), 'Body.', r.stderr);
});

test('the merge bot squashes with the body only, footer stripped (#304: commit lines reached main)', () => {
  const r = spawnSync('python3', ['scripts/dev/merge_when_green.py', '--selftest'], { cwd: root, encoding: 'utf8' });
  assert.equal(r.status, 0, r.stdout + r.stderr);
  const out = spawnSync('python3', ['-c', [
    'import sys, json; sys.path.insert(0, "scripts/dev")',
    'import merge_when_green as M',
    'pr = {"number": 319, "title": "Fix", "body": "Body.\\n\\n\\U0001F916 Generated with [Claude Code](https://claude.com/claude-code)\\n"}',
    'print(json.dumps(M.squash_message(pr)))',
  ].join('\n')], { cwd: root, encoding: 'utf8' });
  assert.deepEqual(JSON.parse(out.stdout), ['Fix (#319)', 'Body.'], out.stderr);
});

test('the PR checks\' guard job runs it on every pull request, with the job token', () => {
  const y = fs.readFileSync(path.join(root, '.github/workflows/pr-checks.yml'), 'utf8');
  const guard = y.slice(y.indexOf('\n  guard:'), y.indexOf('\n  node-tests:'));
  const at = guard.indexOf('- name: no AI footer in the pull request');
  assert.ok(at > 0, 'the step is in the guard job');
  const step = guard.slice(at, guard.indexOf('\n      - ', at + 5));
  assert.match(step, /if: github\.event_name == 'pull_request'/);
  assert.match(step, /GH_TOKEN: \$\{\{ github\.token \}\}/);
  assert.match(step, /run: python3 scripts\/dev\/ai_footer_check\.py\s*$/);
});

test('a long pull request body warns and passes (Nov 5: say what changed for readers)', () => {
  const tmp = fs.mkdtempSync(path.join(process.env.TMPDIR || '/tmp', 'aifoot-'));
  const ev = path.join(tmp, 'event.json');
  fs.writeFileSync(ev, JSON.stringify({ pull_request: { number: 9, body: 'Town pages show the bid date. '.repeat(50) } }));
  const env = { ...process.env, GITHUB_EVENT_PATH: ev, GITHUB_REPOSITORY: 'dnilgis/agsist', GITHUB_API_URL: 'http://127.0.0.1:9', GH_TOKEN: '', GITHUB_ACTIONS: 'true' };
  const r = spawnSync('python3', ['scripts/dev/ai_footer_check.py'], { cwd: root, encoding: 'utf8', env });
  assert.equal(r.status, 0, r.stdout + r.stderr);
  assert.match(r.stdout, /::warning title=Long wording::the pull request body is \d+ characters .*method goes in private notes/);
  const short = path.join(tmp, 'short.json');
  fs.writeFileSync(short, JSON.stringify({ pull_request: { number: 9, body: 'Town pages show the bid date.' } }));
  const s = spawnSync('python3', ['scripts/dev/ai_footer_check.py'], { cwd: root, encoding: 'utf8', env: { ...env, GITHUB_EVENT_PATH: short } });
  assert.equal(s.status, 0, s.stdout + s.stderr);
  assert.doesNotMatch(s.stdout, /Long wording/);
  fs.rmSync(tmp, { recursive: true, force: true });
});
